import React, { useRef } from 'react';
import { useIntl } from 'react-intl';

import { UndoIcon } from '@dynatrace/strato-icons';

import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { isReset } from '../../../core/functions/toolbarEvents.js';
import { useA11yToolbarTabIndex } from '../../../core/hooks/useA11yToolbarTabIndex.js';
import { useOverlaysEvents } from '../../../core/hooks/useOverlaysEvents.js';
import { useToolbarEvent } from '../../../core/hooks/useToolbarEvent.js';
import {
  useCurrentDomainState,
  useZoomState,
} from '../../hooks/store/selectors.js';
import { useSetResetZoomState } from '../../hooks/store/state-setters.js';
import { useHistogramInteractions } from '../../hooks/useHistogramInteractions.js';
import { HISTOGRAM_MESSAGES } from '../../messages/tooltip-text.js';

export const ResetButton = () => {
  const resetButtonRef = useRef<HTMLButtonElement>();
  const tabIndex = useA11yToolbarTabIndex('reset');
  const resetState = useSetResetZoomState();
  const intl = useIntl();
  const currentDomain = useCurrentDomainState();
  const isChartWithoutZoom = !currentDomain;
  const { zoomOutEnabled } = useZoomState();
  const { zoom, zoomX } = useHistogramInteractions();
  const { overlayRef } = useOverlaysEvents();
  const hasZoomInteractions = zoom?.enabled || zoomX?.enabled;

  /** Handles the zoom reset when a 'enter' keyboard event happens.
   * @param event - A keyboard event param.
   */
  function handleZoomResetKeyboardMode(event: KeyboardEvent) {
    if (event.code === 'Enter') {
      resetState();
    }
  }

  useToolbarEvent<KeyboardEvent>(
    'keydown',
    resetState,
    isReset,
    zoomOutEnabled,
    overlayRef?.current as HTMLDivElement,
  );

  return hasZoomInteractions ? (
    <ChartToolbarRenderer.Control
      ref={resetButtonRef}
      prefixIcon={<UndoIcon />}
      tooltipText={intl.formatMessage(HISTOGRAM_MESSAGES.resetMode)}
      tooltipKeyShortcut={'R'}
      onKeyDown={handleZoomResetKeyboardMode}
      onClick={resetState}
      tabIndex={tabIndex}
      disabled={isChartWithoutZoom}
    />
  ) : null;
};

ResetButton['displayName'] = 'ResetButton';
